window.AvatarPicker=(()=>{
 let catalog,dialog,resolve,mode='cartoons',selected=null,upload=null,busy=false,initial='?',generation=0;
 const $=id=>document.getElementById(id);
 function finish(value){if(busy)return;generation++;dialog.close();const done=resolve;resolve=null;done?.(value)}
 function preview(src,label){$('avatar-preview').replaceChildren();if(src){const img=document.createElement('img');img.src=src;img.alt=label;$('avatar-preview').append(img)}else $('avatar-preview').textContent=initial;$('avatar-selected-name').textContent=label;}
 function refresh(){dialog.querySelectorAll('[data-picture-mode]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.pictureMode===mode));b.disabled=busy});$('avatar-grid').hidden=mode!=='cartoons';$('avatar-upload-panel').hidden=mode!=='upload';$('avatar-initial-panel').hidden=mode!=='initial';$('avatar-shuffle').hidden=mode!=='cartoons';$('avatar-use').disabled=busy||(mode==='cartoons'?!selected:mode==='upload'?!upload:false);for(const id of ['avatar-cancel','avatar-close','avatar-shuffle','avatar-file'])$(id).disabled=busy;dialog.querySelectorAll('[data-avatar]').forEach(b=>{b.disabled=busy;b.setAttribute('aria-pressed',String(b.dataset.avatar===selected?.id))});if(mode==='initial')preview(null,'Your username initial');else if(mode==='upload')preview(upload,'Photo preview');else preview(selected?.url,selected?.name||'Choose a cartoon');}
 async function convert(src){const image=new Image();image.src=src;await image.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,256,256);const size=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-size)/2,(image.height-size)/2,size,size,0,0,256,256);return canvas.toDataURL('image/jpeg',.9)}
 async function open(options={}){
 if(resolve)return null;
 if(!dialog){dialog=document.createElement('dialog');dialog.id='avatar-picker';dialog.setAttribute('aria-labelledby','avatar-picker-title');dialog.innerHTML='<div class="picture-dialog-heading"><h2 id="avatar-picker-title">Profile picture</h2><button type="button" id="avatar-close" aria-label="Close picture picker">×</button></div><div class="picture-tabs" role="group" aria-label="Picture source"><button type="button" data-picture-mode="cartoons">Cartoons</button><button type="button" data-picture-mode="upload">Upload photo</button><button type="button" data-picture-mode="initial">Use initial</button></div><div id="avatar-preview"></div><p id="avatar-selected-name"></p><div id="avatar-grid" role="group" aria-label="Cartoon avatars"></div><div id="avatar-upload-panel" hidden><label>Choose a photo<input type="file" id="avatar-file" accept="image/png,image/jpeg"></label><p>JPEG or PNG, up to 8 MB. A centered square crop is shown above.</p></div><div id="avatar-initial-panel" hidden><p>Use the first letter of your username instead of a picture.</p></div><p id="avatar-error" role="status"></p><div class="avatar-actions"><button type="button" id="avatar-shuffle" class="secondary">Shuffle</button><button type="button" id="avatar-cancel" class="secondary">Cancel</button><button type="button" id="avatar-use" class="primary">Use this picture</button></div>';document.body.append(dialog);
 dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null)});for(const id of ['avatar-cancel','avatar-close'])$(id).onclick=()=>finish(null);dialog.querySelectorAll('[data-picture-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.pictureMode;$('avatar-error').textContent='';refresh()});$('avatar-shuffle').onclick=()=>{if(catalog?.length){selected=catalog[Math.floor(Math.random()*catalog.length)];refresh()}};
 $('avatar-file').onchange=async()=>{const file=$('avatar-file').files[0];if(!file)return;busy=true;upload=null;refresh();try{if(!['image/jpeg','image/png'].includes(file.type)||file.size>8*1024*1024)throw Error('Choose a JPEG or PNG smaller than 8 MB.');const url=URL.createObjectURL(file);try{upload=await convert(url)}finally{URL.revokeObjectURL(url)}$('avatar-error').textContent='';}catch(e){$('avatar-error').textContent=e.message}finally{busy=false;refresh()}};
 $('avatar-use').onclick=async()=>{if(busy)return;if(mode==='initial'){finish('');return}if(mode==='upload'){if(upload)finish(upload);return}if(!selected)return;busy=true;refresh();try{const value=await convert(selected.url);busy=false;finish(value)}catch{$('avatar-error').textContent='Could not load this picture. Please try again.'}finally{busy=false;refresh()}};
 }
 initial=Array.from((options.username||'?').trim())[0].toUpperCase();mode='cartoons';selected=null;upload=null;$('avatar-file').value='';$('avatar-error').textContent='';const id=++generation;const promise=new Promise(r=>resolve=r);refresh();dialog.showModal();
 try{if(!catalog){const r=await fetch('/avatars/catalog.json');if(!r.ok)throw Error();catalog=await r.json()}if(id!==generation)return promise;const grid=$('avatar-grid');grid.replaceChildren();for(const a of catalog){const b=document.createElement('button');b.type='button';b.dataset.avatar=a.id;b.setAttribute('aria-label',a.name);const img=document.createElement('img');img.src=a.url;img.alt='';const label=document.createElement('span');label.textContent=a.name;b.append(img,label);b.onclick=()=>{selected=a;refresh()};grid.append(b)}refresh()}catch{if(id===generation)$('avatar-error').textContent='Cartoons could not load. Upload a photo, use your initial, or try again.'}
 return promise;
 }
 return {open};
})();
